import type { GGDiscoveryStore } from "@grida/ai";
/**
 * GRIDA-SEC-004 — `/images/generate` route (BYOK image generation, #908).
 *
 * Native host image generation. The route resolves a curated model through
 * the shared image operation and returns generated bytes plus optional host
 * persistence receipts. Provider credentials remain inside the operation.
 *
 * Security contract (reviewed):
 *   - Reads `_getKey` internally (legal — sidecar only). The response carries
 *     base64 image bytes + provider id only: never the key, never the raw
 *     upstream JSON.
 *   - `model_id` is a closed catalog lookup (curated `listed` cards only) and
 *     `provider` is `oneOf` the fixed image providers — there is NO
 *     user-supplied base URL, so this opens no new egress beyond the three
 *     fixed provider hosts (unlike the endpoint routes, issue #806).
 *
 * Billing contract (#908, Phase 4 + GRIDA-SEC-006): the BYOK arms NEVER
 * enter the web Grida-billed image seam (`editor/lib/ai/server.ts`) — the
 * user's own key pays the provider directly, no Grida credit is metered,
 * and this sidecar route never sets the WEB seam's billing trigger. The
 * `gg` hosted arm is not a billing leak: its billing happens
 * server-side at the hosted endpoint (Bearer session token; the seam
 * gates + meters there), never in this process.
 */

import { createHash, timingSafeEqual } from "node:crypto";
import type { Hono } from "hono";
import { ImageClient } from "@grida/ai";
import type { MediaPersistence, SecretsStore } from "@grida/daemon/server";
import type { ModelCatalogStore } from "../../providers/model-catalog";
import {
  ImageModelUnavailableError,
  resolveImageModel,
} from "../../providers/resolve-image";
import { mediaGenerationError } from "./media-generation-errors";
import { body, v } from "@grida/daemon/server";
import type { ProviderHttp } from "../../providers/http";
import type { ImageGeneratedImage } from "../../protocol/images";
import { GeneratedMediaPersistence } from "./generated-media-persistence";

const IMAGE_PROVIDERS = ["vercel", "fal", "openrouter", "gg"] as const;
const RETAINED_IMAGE_TYPE = "application/vnd.grida.retained-image+json";
const RETAINED_IMAGE_FIELDS = new Set([
  "model_id",
  "binding_id",
  "prompt",
  "provider",
  "background",
  "credential",
  "n",
]);
const RETAINED_IMAGE_MIME_TYPES = new Set([
  "image/png",
  "image/jpeg",
  "image/webp",
  "image/gif",
]);

export type ImagesRoutesDeps = {
  secrets: SecretsStore;
  media?: MediaPersistence | null;
  /** Image catalogue for resolution; absent ⇒ the bundled one. */
  catalog?: ModelCatalogStore;
  gg_catalog?: GGDiscoveryStore;
  // GRIDA-GG: provider — the optional hosted image arm.
  /** GRIDA-SEC-006 — hosted provider deps; absent ⇒ grida never resolves. */
  gg?: import("../../providers/gg-session").GridaGatewaySessionStore;
  gg_base_url?: string;
  provider_http?: ProviderHttp;
};

export function registerImagesRoutes(app: Hono, deps: ImagesRoutesDeps) {
  const { secrets, gg, gg_base_url, provider_http, catalog, gg_catalog } = deps;

  app.post("/images/generate", async (c) => {
    const r = await body(c, {
      model_id: v.string,
      prompt: v.string,
      provider: v.optional(v.oneOf(IMAGE_PROVIDERS)),
      width: v.optional(v.number),
      height: v.optional(v.number),
      aspect_ratio: v.optional(v.string),
      n: v.optional(v.number),
      seed: v.optional(v.number),
      quality: v.optional(v.string),
      background: v.optional(
        v.oneOf(["auto", "opaque", "transparent"] as const)
      ),
    });
    if (!r.ok) return r.res;
    const {
      model_id,
      prompt,
      provider,
      width,
      height,
      aspect_ratio,
      n,
      seed,
      quality,
      background,
    } = r.data;
    const retainedOnly = c.req.header("accept") === RETAINED_IMAGE_TYPE;
    let imageKeys: Pick<SecretsStore, "_getKey"> = secrets;
    let requiredBinding: string | undefined;
    if (retainedOnly) {
      const request = await c.req.json<Record<string, unknown>>();
      const credential = retainedCredential(request.credential);
      if (
        (provider !== "openrouter" && provider !== "vercel") ||
        !credential ||
        typeof request.binding_id !== "string" ||
        !request.binding_id ||
        request.binding_id.length > 256 ||
        (n ?? 1) !== 1 ||
        !prompt.trim() ||
        Buffer.byteLength(prompt) > 8 * 1024 ||
        Object.keys(request).some((field) => !RETAINED_IMAGE_FIELDS.has(field))
      )
        return c.json({ error: "invalid retained image request" }, 400);
      requiredBinding = request.binding_id;
      imageKeys = {
        async _getKey(id) {
          if (id !== provider) return null;
          const key = (await secrets._getKey(id))?.trim();
          if (!key) return null;
          const proof = createHash("sha256")
            .update("grida-desktop-image-key-v1\0")
            .update(credential.nonce)
            .update("\0")
            .update(key)
            .digest();
          return timingSafeEqual(proof, credential.proof) ? key : null;
        },
      };
    }

    let resolved;
    try {
      resolved = await resolveImageModel(
        {
          secrets: imageKeys,
          gg,
          gg_base_url,
          provider_http,
          catalog,
          gg_catalog,
        },
        model_id,
        { ...(provider ? { explicit: provider } : {}), background }
      );
    } catch (e) {
      if (e instanceof ImageModelUnavailableError) {
        return c.json(
          { error: e.message, code: e.code, model_id: e.model_id },
          400
        );
      }
      return c.json({ error: "image generation failed", model_id }, 502);
    }
    if (requiredBinding && resolved.binding_id !== requiredBinding)
      return c.json({ error: "image model unavailable" }, 400);

    const size =
      width && height
        ? (`${Math.round(width)}x${Math.round(height)}` as `${number}x${number}`)
        : undefined;

    let generation;
    try {
      generation = await resolved.generate({
        prompt,
        n: n ?? 1,
        ...(size ? { size } : {}),
        ...(aspect_ratio
          ? { aspect_ratio: aspect_ratio as `${number}:${number}` }
          : {}),
        ...(seed !== undefined ? { seed } : {}),
        ...(quality ? { quality } : {}),
        signal: c.req.raw.signal,
      });
    } catch (e) {
      if (
        retainedOnly &&
        e instanceof ImageClient.Failure &&
        e.code === "provider_unavailable"
      )
        return c.json({ error: "image model unavailable" }, 400);
      if (e instanceof ImageClient.Failure && e.code === "invalid_input") {
        return c.json({ error: "invalid image input", code: e.code }, 400);
      }
      return mediaGenerationError(c, {
        error:
          e instanceof ImageClient.Failure
            ? e
            : new ImageClient.Failure("generation_failed"),
        scope: "agent-host-images",
        label: "image generation failed",
        model_id,
        provider_id: resolved.provider_id,
      });
    }

    if (retainedOnly) {
      const [image] = generation.images;
      if (!image || generation.images.length !== 1)
        return c.json({ error: "image generation result unverified" }, 502);
      const fileName = GeneratedMediaPersistence.fileName(
        "image",
        0,
        image.media_type
      );
      let stored;
      if (
        fileName &&
        deps.media &&
        RETAINED_IMAGE_MIME_TYPES.has(image.media_type)
      ) {
        try {
          stored = await deps.media.save({
            file_name: fileName,
            media_type: image.media_type,
            bytes: image.data,
          });
        } catch {
          console.warn("[grida-agent] generated media could not be saved");
        }
      }
      return c.json({
        model_id: resolved.model_id,
        provider_id: resolved.provider_id,
        stored_media: stored ?? null,
      });
    }

    const images: ImageGeneratedImage[] = [];
    for (const [index, generated] of generation.images.entries()) {
      const image = {
        base64: Buffer.from(generated.data).toString("base64"),
        media_type: generated.media_type,
      };
      const fileName = GeneratedMediaPersistence.fileName(
        "image",
        index,
        image.media_type
      );
      const storedMedia = fileName
        ? await GeneratedMediaPersistence.save(deps.media, {
            ...image,
            file_name: fileName,
          })
        : undefined;
      images.push({
        ...image,
        ...(storedMedia ? { stored_media: storedMedia } : {}),
      });
    }

    return c.json({
      model_id: resolved.model_id,
      provider_id: resolved.provider_id,
      images,
    });
  });
}

function retainedCredential(value: unknown) {
  if (!value || typeof value !== "object" || Array.isArray(value))
    return undefined;
  const { nonce, proof } = value as Record<string, unknown>;
  if (
    Object.keys(value).length !== 2 ||
    typeof nonce !== "string" ||
    !/^[a-f0-9]{32}$/.test(nonce) ||
    typeof proof !== "string" ||
    !/^[a-f0-9]{64}$/.test(proof)
  )
    return undefined;
  return { nonce, proof: Buffer.from(proof, "hex") };
}
